#include <cstdio>
#include <vector>
#include <cfloat>
#include <limits>
static unsigned checks=0,failures=0,calls=0;static void Check(bool b,const char*s){++checks;if(!b){++failures;printf("FAIL %s\n",s);}}
struct GameData{};static GameData data,other;
struct Item{GameData*data;bool isEquipped,isUnique;int quantity,owner;float chargesLeft,originalFullChargeAmount,quality;void*manufacturerData;void*materialData;void*coloriseData;Item():data(&::data),isEquipped(false),isUnique(false),quantity(1),owner(1),chargesLeft(1),originalFullChargeAmount(1),quality(1),manufacturerData(0),materialData(0),coloriseData(0){}GameData*getGameData(){return data;}bool canStackWith(Item*p){++calls;return owner==p->owner;}};
template<class T>struct lektor:std::vector<T>{};struct Inventory{lektor<Item*>items;const lektor<Item*>&getAllItems(){return items;}};
