personal.quality=2;Check(!FungibleInventory(&inv,&candidate,&data),"personal quality variant refused");personal=Item();personal.manufacturerData=(void*)1;Check(!FungibleInventory(&inv,&candidate,&data),"personal manufacturer variant refused");personal=Item();personal.materialData=(void*)1;Check(!FungibleInventory(&inv,&candidate,&data),"personal material variant refused");personal=Item();personal.coloriseData=(void*)1;Check(!FungibleInventory(&inv,&candidate,&data),"personal colour variant refused");personal=Item();personal.owner=2;Check(!FungibleInventory(&inv,&candidate,&data),"native stolen/proper-owner mismatch refused");personal=Item();personal.chargesLeft=.5f;Check(!FungibleInventory(&inv,&candidate,&data),"partial charge stock never split/reset");personal=Item();personal.chargesLeft=personal.originalFullChargeAmount=5;Check(!FungibleInventory(&inv,&candidate,&data),"different fully charged capacity cannot replace personal baseline");personal=Item();personal.chargesLeft=personal.originalFullChargeAmount=std::numeric_limits<float>::infinity();Check(!FungibleInventory(&inv,&candidate,&data),"infinite full charge amount refused");personal=Item();candidate.chargesLeft=candidate.originalFullChargeAmount=std::numeric_limits<float>::infinity();Check(!FungibleInventory(&inv,&candidate,&data),"infinite candidate full charge refused");candidate=Item();personal=Item();personal.isEquipped=true;Check(!FungibleInventory(&inv,&candidate,&data),"equipped same-data item excludes uncertain ownership");personal=Item();personal.isUnique=true;Check(!FungibleInventory(&inv,&candidate,&data),"unique same-data item excludes uncertain ownership");personal=Item();personal.data=&other;Check(FungibleInventory(&inv,&candidate,&data),"unrelated materials do not affect owned return");
inv.items.assign(33,&candidate);Check(!FungibleInventory(&inv,&candidate,&data),"matching stack scan bounded at32");inv.items.assign(129,&candidate);calls=0;Check(!FungibleInventory(&inv,&candidate,&data)&&calls==0,"oversized inventory refused without native compatibility loop");Check(FungibleInventory(NULL,&candidate,&data),"absent backpack harmless");
